mapper.select:
SELECT EXISTS (
    SELECT 1
      FROM members
     WHERE id = #{id}
       AND is_deleted IS NOT TRUE
)

SELECT EXISTS (
    SELECT 1
      FROM members
     WHERE mail = #{mail}
)

mapper.update:
UPDATE members
   SET is_deleted = true
 WHERE id = #{id}

UPDATE members
SET point = point + #{points}
WHERE id = #{id} AND is_deleted = false

mapper.select:
SELECT COALESCE(SUM(points), 0)
FROM point_histories
WHERE member_id = #{memberId}
  AND reason = #{reason}
